REGISTROS = [
    ("ce-1-1", "ce", "art. 1.1", "a1", "España se constituye en un Estado social y democrático de Derecho", "España es un Estado social y democrático de Derecho. Sus valores superiores son la libertad, la justicia, la igualdad y el pluralismo político."),
    ("ce-1-2", "ce", "art. 1.2", "a1", "La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.", "Los poderes del Estado proceden del pueblo."),
    ("ce-1-3", "ce", "art. 1.3", "a1", "La forma política del Estado español es la Monarquía parlamentaria.", "España es una monarquía parlamentaria."),
    ("ce-2", "ce", "art. 2", "a2", "reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran", "La Constitución se fundamenta en la unidad de la Nación española y reconoce el derecho a la autonomía y la solidaridad entre territorios."),
    ("ce-9-1", "ce", "art. 9.1", "a9", "Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.", "Todos, también las autoridades, deben cumplir la Constitución y las demás normas."),
    ("ce-9-2", "ce", "art. 9.2", "a9", "promover las condiciones para que la libertad y la igualdad del individuo y de los grupos en que se integra sean reales y efectivas", "Los poderes públicos deben facilitar que la libertad y la igualdad sean reales y que todos puedan participar en la vida pública."),
    ("ce-9-3", "ce", "art. 9.3", "a9", "La Constitución garantiza el principio de legalidad, la jerarquía normativa, la publicidad de las normas", "Garantiza, entre otros, la legalidad, la jerarquía normativa, la publicidad de las normas, la seguridad jurídica y la prohibición de la arbitrariedad."),
    ("ce-14", "ce", "art. 14", "a14", "Los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna", "Igualdad ante la ley y prohibición de discriminación."),
    ("ce-18-4", "ce", "art. 18.4", "a18", "La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar", "Base de la protección de datos personales, dentro de los derechos fundamentales."),
    ("ce-21", "ce", "art. 21", "a21", "Se reconoce el derecho de reunión pacífica y sin armas.", "Reunirse no necesita autorización previa. Las manifestaciones en lugares de tránsito público se comunican antes a la autoridad."),
    ("ce-23-1", "ce", "art. 23.1", "a23", "Los ciudadanos tienen el derecho a participar en los asuntos públicos, directamente o por medio de representantes", "Derecho a participar en los asuntos públicos, también eligiendo representantes en elecciones periódicas."),
    ("ce-24", "ce", "art. 24", "a24", "a no declarar contra sí mismos, a no confesarse culpables y a la presunción de inocencia", "Derecho a la tutela de los jueces, a la defensa, a un proceso con garantías y a la presunción de inocencia."),
    ("ce-27", "ce", "art. 27", "a27", "Todos tienen el derecho a la educación.", "Derecho fundamental. La enseñanza básica es obligatoria y gratuita (art. 27.4)."),
    ("ce-30-1", "ce", "art. 30.1", "a30", "Los españoles tienen el derecho y el deber de defender a España.", "Derecho y deber de la Sección 2.ª del Capítulo II."),
    ("ce-31-1", "ce", "art. 31.1", "a31", "Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica", "Deber de pagar impuestos según la capacidad económica, con un sistema tributario justo y progresivo."),
    ("ce-35-1", "ce", "art. 35.1", "a35", "Todos los españoles tienen el deber de trabajar y el derecho al trabajo", "Derecho y deber de la Sección 2.ª del Capítulo II."),
    ("ce-43-1", "ce", "art. 43.1", "a43", "Se reconoce el derecho a la protección de la salud.", "Principio rector de la política social y económica (Capítulo III)."),
    ("ce-47", "ce", "art. 47", "a47", "Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.", "Principio rector de la política social y económica (Capítulo III)."),
    ("ce-53-1", "ce", "art. 53.1", "a53", "Los derechos y libertades reconocidos en el Capítulo segundo del presente Título vinculan a todos los poderes públicos.", "Solo una ley que respete su contenido esencial puede regular el ejercicio de estos derechos."),
    ("ce-53-2", "ce", "art. 53.2", "a53", "a través del recurso de amparo ante el Tribunal Constitucional", "La igualdad (art. 14) y los derechos de la Sección 1.ª se protegen en los tribunales por un procedimiento preferente y, en su caso, con recurso de amparo."),
    ("ce-53-3", "ce", "art. 53.3", "a53", "Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.", "Los principios rectores orientan las leyes y la actuación pública, pero se reclaman ante los jueces según lo que digan las leyes que los desarrollan."),
    ("ce-54", "ce", "art. 54", "a54", "alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos", "El Defensor del Pueblo defiende los derechos y puede supervisar la actividad de la Administración."),
    ("ce-56-1", "ce", "art. 56.1", "a56", "El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones", "El Rey es el Jefe del Estado y ejerce las funciones que le atribuyen la Constitución y las leyes."),
    ("ce-56-3", "ce", "art. 56.3", "a56", "Sus actos estarán siempre refrendados en la forma establecida en el artículo 64, careciendo de validez sin dicho refrendo", "Los actos del Rey necesitan refrendo para ser válidos."),
    ("ce-62", "ce", "art. 62", "a62", "Sancionar y promulgar las leyes.", "Corresponde al Rey, entre otras funciones: sancionar y promulgar leyes, convocar y disolver las Cortes, proponer candidato a la Presidencia y nombrar a los miembros del Gobierno a propuesta de su Presidente."),
    ("ce-64", "ce", "art. 64", "a64", "De los actos del Rey serán responsables las personas que los refrenden.", "Refrendan el Presidente del Gobierno y, en su caso, los ministros; el nombramiento del Presidente y la disolución del artículo 99, el Presidente del Congreso."),
    ("ce-66", "ce", "art. 66", "a66", "Las Cortes Generales ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno", "Las Cortes Generales, formadas por el Congreso y el Senado, representan al pueblo español."),
    ("ce-68-1", "ce", "art. 68.1", "a68", "El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados", "La Constitución fija una horquilla; la cifra exacta la fija la ley electoral."),
    ("ce-68-4", "ce", "art. 68.4", "a68", "El Congreso es elegido por cuatro años.", "El mandato termina a los cuatro años o el día de la disolución."),
    ("ce-69-1", "ce", "art. 69.1", "a69", "El Senado es la Cámara de representación territorial.", "Tiene senadores elegidos en provincias, islas, Ceuta y Melilla, y senadores designados por las comunidades autónomas."),
    ("ce-69-3", "ce", "art. 69.3 (reforma de 2026)", "a69", "La eficacia de la creación de las circunscripciones electorales de Ibiza y Formentera quedará pospuesta hasta la convocatoria de las primeras elecciones al Senado", "Nota del BOE sobre la reforma de 19 de mayo de 2026 (BOE-A-2026-10881): Ibiza y Formentera eligen un senador cada una."),
    ("ce-69-5", "ce", "art. 69.5", "a69", "Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes", "Los parlamentos autonómicos designan senadores según la población de cada comunidad."),
    ("ce-72-2", "ce", "art. 72.2", "a72", "Las Cámaras eligen sus respectivos Presidentes y los demás miembros de sus Mesas.", "El Presidente del Congreso lo elige el propio Congreso."),
    ("ce-75-1", "ce", "art. 75.1", "a75", "Las Cámaras funcionarán en Pleno y por Comisiones.", "Las Comisiones pueden aprobar leyes por delegación del Pleno, salvo excepciones (art. 75.2 y 75.3)."),
    ("ce-78-1", "ce", "art. 78.1", "a78", "En cada Cámara habrá una Diputación Permanente compuesta por un mínimo de veintiún miembros", "La Diputación Permanente vela por los poderes de la Cámara cuando no está reunida o ha sido disuelta."),
    ("ce-81", "ce", "art. 81", "a81", "exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto", "Leyes orgánicas: derechos fundamentales, Estatutos de Autonomía, régimen electoral general y otras materias previstas."),
    ("ce-82-1", "ce", "art. 82.1", "a82", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley", "La delegación es expresa, para una materia concreta y con plazo; no cabe en materias de ley orgánica."),
    ("ce-86-1", "ce", "art. 86.1", "a86", "En caso de extraordinaria y urgente necesidad, el Gobierno podrá dictar disposiciones legislativas provisionales", "Los decretos-leyes no pueden afectar a las instituciones básicas, a los derechos del Título I, al régimen autonómico ni al derecho electoral general."),
    ("ce-86-2", "ce", "art. 86.2", "a86", "en el plazo de los treinta días siguientes a su promulgación", "El Congreso debe pronunciarse sobre su convalidación o derogación en ese plazo."),
    ("ce-87", "ce", "art. 87", "a87", "La iniciativa legislativa corresponde al Gobierno, al Congreso y al Senado", "También pueden promoverla las Asambleas autonómicas y la ciudadanía con al menos 500.000 firmas, salvo en ciertas materias."),
    ("ce-88", "ce", "art. 88", "a88", "Los proyectos de ley serán aprobados en Consejo de Ministros, que los someterá al Congreso", "Los proyectos van acompañados de una exposición de motivos y de antecedentes."),
    ("ce-90-2", "ce", "art. 90.2", "a90", "puede, mediante mensaje motivado, oponer su veto o introducir enmiendas al mismo. El veto deberá ser aprobado por mayoría absoluta.", "El Senado tiene dos meses. El Congreso levanta el veto por mayoría absoluta o, pasados dos meses, por mayoría simple, y decide sobre las enmiendas por mayoría simple."),
    ("ce-90-3", "ce", "art. 90.3", "a90", "se reducirá al de veinte días naturales en los proyectos declarados urgentes", "Plazo del Senado en los proyectos urgentes."),
    ("ce-91", "ce", "art. 91", "a91", "El Rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales", "Después las promulga y ordena su inmediata publicación."),
    ("ce-96-1", "ce", "art. 96.1", "a96", "Los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, formarán parte del ordenamiento interno.", "Los tratados publicados forman parte del ordenamiento español."),
    ("ce-97", "ce", "art. 97", "a97", "El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado.", "Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes."),
    ("ce-98", "ce", "art. 98", "a98", "El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros del mismo", "El Gobierno lo forman el Presidente, los Vicepresidentes en su caso, los Ministros y los demás miembros que establezca la ley."),
    ("ce-99-1", "ce", "art. 99.1", "a99", "el Rey, previa consulta con los representantes designados por los Grupos políticos con representación parlamentaria", "Tras las consultas, y a través del Presidente del Congreso, el Rey propone un candidato a la Presidencia del Gobierno."),
    ("ce-99-3", "ce", "art. 99.3", "a99", "De no alcanzarse dicha mayoría, se someterá la misma propuesta a nueva votación cuarenta y ocho horas después", "Primera votación: mayoría absoluta de los miembros del Congreso. Segunda, 48 horas después: mayoría simple."),
    ("ce-99-5", "ce", "art. 99.5", "a99", "Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza", "En ese caso, el Rey disuelve ambas Cámaras y convoca elecciones con el refrendo del Presidente del Congreso."),
    ("ce-100", "ce", "art. 100", "a100", "Los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de su Presidente.", "Los ministros los propone el Presidente del Gobierno."),
    ("ce-101", "ce", "art. 101", "a101", "El Gobierno cesante continuará en funciones hasta la toma de posesión del nuevo Gobierno.", "El Gobierno cesa tras las elecciones generales, por pérdida de la confianza parlamentaria o por dimisión o fallecimiento de su Presidente."),
    ("ce-103-1", "ce", "art. 103.1", "a103", "La Administración Pública sirve con objetividad los intereses generales", "Actúa con sometimiento pleno a la ley y al Derecho."),
    ("ce-108", "ce", "art. 108", "a108", "El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados.", "Responsabilidad política del Gobierno ante el Congreso."),
    ("ce-111-1", "ce", "art. 111.1", "a111", "El Gobierno y cada uno de sus miembros están sometidos a las interpelaciones y preguntas que se le formulen en las Cámaras.", "Una interpelación puede dar lugar a una moción en la que la Cámara fija su posición (art. 111.2)."),
    ("ce-112", "ce", "art. 112", "a112", "La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados.", "La plantea el Presidente del Gobierno, tras deliberar el Consejo de Ministros, sobre su programa o una declaración de política general."),
    ("ce-113", "ce", "art. 113", "a113", "La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato", "Se aprueba por mayoría absoluta y no se vota hasta pasados cinco días desde su presentación."),
    ("ce-114", "ce", "art. 114", "a114", "el candidato incluido en aquélla se entenderá investido de la confianza de la Cámara", "Si se niega la confianza o prospera una moción de censura, el Gobierno presenta su dimisión."),
    ("ce-115-1", "ce", "art. 115.1", "a115", "podrá proponer la disolución del Congreso, del Senado o de las Cortes Generales, que será decretada por el Rey", "La propone el Presidente del Gobierno, previa deliberación del Consejo de Ministros; el decreto fija la fecha de las elecciones."),
    ("ce-117-1", "ce", "art. 117.1", "a117", "Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley", "La justicia emana del pueblo y se administra en nombre del Rey."),
    ("ce-117-3", "ce", "art. 117.3", "a117", "juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes", "Solo los juzgados y tribunales ejercen la potestad jurisdiccional."),
    ("ce-122", "ce", "art. 122", "a122", "El Consejo General del Poder Judicial es el órgano de gobierno del mismo.", "Lo integran el Presidente del Tribunal Supremo y veinte miembros por cinco años: doce entre jueces y magistrados según la ley orgánica, y cuatro a propuesta del Congreso y cuatro del Senado, por tres quintos."),
    ("ce-123-1", "ce", "art. 123.1", "a123", "El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes", "Salvo en materia de garantías constitucionales."),
    ("ce-124", "ce", "art. 124", "a124", "tiene por misión promover la acción de la justicia en defensa de la legalidad", "El Fiscal General del Estado lo nombra el Rey a propuesta del Gobierno, oído el Consejo General del Poder Judicial (art. 124.4)."),
    ("ce-136-1", "ce", "art. 136.1", "a136", "El Tribunal de Cuentas es el supremo órgano fiscalizador de las cuentas y de la gestión económica de Estado", "Depende directamente de las Cortes Generales."),
    ("ce-137", "ce", "art. 137", "a137", "El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.", "Todas estas entidades tienen autonomía para gestionar sus intereses."),
    ("ce-140", "ce", "art. 140", "a140", "Su gobierno y administración corresponde a sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales.", "Los vecinos eligen a los concejales; los alcaldes los eligen los concejales o los vecinos."),
    ("ce-141", "ce", "art. 141", "a141", "La provincia es una entidad local con personalidad jurídica propia", "La gobiernan Diputaciones u otras corporaciones representativas; en los archipiélagos, las islas tienen Cabildos o Consejos."),
    ("ce-143-1", "ce", "art. 143.1", "a143", "podrán acceder a su autogobierno y constituirse en Comunidades Autónomas", "Vía para que provincias y territorios insulares se constituyan en comunidades autónomas."),
    ("ce-147-1", "ce", "art. 147.1", "a147", "los Estatutos serán la norma institucional básica de cada Comunidad Autónoma", "El Estado reconoce los Estatutos como parte de su ordenamiento."),
    ("ce-152-1", "ce", "art. 152.1", "a152", "un Presidente, elegido por la Asamblea, de entre sus miembros, y nombrado por el Rey", "Organización institucional prevista para los Estatutos aprobados por la vía del artículo 151: Asamblea, Consejo de Gobierno y Presidente."),
    ("ce-159", "ce", "art. 159", "a159", "El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey", "Cuatro a propuesta del Congreso y cuatro del Senado (tres quintos), dos del Gobierno y dos del CGPJ; por nueve años, renovados por terceras partes cada tres."),
    ("ce-161-1", "ce", "art. 161.1", "a161", "Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley.", "También resuelve recursos de amparo y conflictos de competencia entre el Estado y las comunidades autónomas."),
    ("ce-163", "ce", "art. 163", "a163", "planteará la cuestión ante el Tribunal Constitucional", "Cuestión de inconstitucionalidad: un juez duda de que una ley aplicable al caso respete la Constitución."),
    ("ce-167", "ce", "art. 167", "a167", "Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.", "Si se pide en quince días, la reforma se somete a referéndum."),
    ("ce-168", "ce", "art. 168", "a168", "se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes", "Procedimiento agravado para la revisión total o para el título preliminar, la Sección 1.ª del Capítulo II del Título I y la Corona; termina con referéndum."),
    ("ce-da1", "ce", "disposición adicional primera", "primera", "La Constitución ampara y respeta los derechos históricos de los territorios forales.", "Base del régimen foral, que se actualiza en el marco de la Constitución y de los Estatutos."),
    ("ce-df", "ce", "disposición final", "df", "Esta Constitución entrará en vigor el mismo día de la publicación de su texto oficial en el boletín oficial del Estado.", "También se publica en las demás lenguas de España."),
    ("lg-1-2", "lg", "art. 1.2", "a1", "El Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros.", "Sus miembros se reúnen en Consejo de Ministros y en Comisiones Delegadas."),
    ("lg-5-1", "lg", "art. 5.1", "a5", "Aprobar los proyectos de ley y su remisión al Congreso de los Diputados", "El Consejo de Ministros aprueba también el proyecto de Presupuestos, los reales decretos-leyes y legislativos y los reglamentos."),
    ("lg-21", "lg", "art. 21", "a21", "limitará su gestión al despacho ordinario de los asuntos públicos", "En funciones no se puede proponer la disolución, plantear la cuestión de confianza, aprobar el proyecto de Presupuestos ni presentar proyectos de ley."),
    ("lg-24-2", "lg", "art. 24.2", "a24", "Disposiciones aprobadas por Real Decreto del Presidente del Gobierno o acordado en el Consejo de Ministros.", "Entre los reglamentos, el real decreto está por encima de la orden ministerial."),
    ("cc-1-2", "cc", "art. 1.2", "a1", "Carecerán de validez las disposiciones que contradigan otra de rango superior.", "Regla de jerarquía entre normas."),
    ("cc-2-1", "cc", "art. 2.1", "art2", "Las leyes entrarán en vigor a los veinte días de su completa publicación en el «Boletín Oficial del Estado»", "Salvo que la propia ley disponga otra cosa."),
    ("cc-2-2", "cc", "art. 2.2", "art2", "Las leyes sólo se derogan por otras posteriores.", "La derogación alcanza a lo que la ley nueva diga expresamente y a lo que sea incompatible con ella."),
    ("loreg-162-1", "loreg", "art. 162.1", None, "El Congreso está formado por trescientos cincuenta Diputados.", "La ley electoral fija la cifra dentro de la horquilla constitucional."),
    ("rc-79-1", "rc", "art. 79.1", "art79", "deberán ser aprobados por la mayoría simple de los miembros presentes del órgano correspondiente", "Regla general de las votaciones del Congreso, salvo mayorías especiales."),
]

