def main(raiz):
    registros = []
    lotes = [(REGISTROS, "2026-10-29", "29-10-2026"), (REGISTROS_H2, "2026-10-30", "30-10-2026"), (REGISTROS_H3, "2026-11-04", "04-11-2026"),
             (REGISTROS_H4A, "2026-11-04", "04-11-2026"), (REGISTROS_H4B, "2026-11-05", "05-11-2026")]
    for lote, consulta, vigente in lotes:
        for id_, clave, articulo, ancla, cita, valor in lote:
            nombre, fuente, url, publicacion = NORMAS[clave]
            r = {
                "id": id_,
                "conjunto": "normas",
                "norma": nombre,
                "articulo": articulo,
                "valor": valor,
                "cita": cita,
                "unidad": "sin unidad",
                "periodo": "texto consolidado vigente el " + vigente,
                "fuente_id": fuente,
                "url": url,
            }
            if ancla:
                r["ancla"] = ancla
            r.update({
                "fecha_publicacion": publicacion,
                "fecha_consulta": consulta,
                "estado": "verificado",
                "etiqueta": "NORMA VIGENTE",
            })
            registros.append(r)
    doc = {
        "meta": {
            "conjunto": "normas",
            "esquema": "dato",
            "version": "0.5.0",
            "actualizado": "2026-11-05",
            "descripcion": "Artículos de normas leídos en el BOE: cita literal breve, resumen y fecha de la versión consolidada.",
        },
        "registros": registros,
    }
    destino = pathlib.Path(raiz) / "data" / "normas.json"
    destino.write_text(json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(len(registros))


if __name__ == "__main__":
    main(sys.argv[1])
